/**
 * The UnicodeMath grammar, checked against the gem.
 *
 * Nothing here is reasoned out. Every expectation is the oracle's own answer,
 * captured by parsing the input through `Plurimath::UnicodeMath::Parser`'s
 * preprocessing and then `UnicodeMath::Parse#parse`, and serialising the
 * Parslet tree with slices flattened to their text — the same projection
 * `plain()` below performs on this port's tree, so the two meet in one shape.
 * Produced against plurimath 0.11.6 at
 * `00c52783877b38f6b8e6e109f1803f96bb34fc62` from a clean checkout.
 *
 * Five groups, each answering a different question.
 *
 * 1. **The gem's own UnicodeMath**: every distinct `expected.unicodemath` in
 *    the pinned `plurimath-testsuite` corpus — 88 of them, the gem's own
 *    `to_unicodemath` output for the shared cases, run back through the
 *    grammar. 5 of those the gem itself refuses.
 * 2. **Real-world UnicodeMath**: the 672 distinct expressions in the upstream
 *    `unicodemath-tests` corpus, which is what the gem's own
 *    `unicodemath_tests_spec.rb` runs against. All 670 non-divergent inputs
 *    are checked at verdict level, and 98 of them carry the full tree —
 *    chosen by a greedy cover over every distinct parent->child edge the
 *    oracle's trees contain, so all 493 edges are exercised rather than an
 *    arbitrary slice.
 * 3. **A sweep**, with trees, not just verdicts: every string of length 1 and 2
 *    over a 30-character alphabet of the operators this grammar branches on,
 *    plus every length-3 string over the structural subset — 4367 inputs, of
 *    which the gem refuses 3444. Ordering bugs surface here: a reordered
 *    alternative turns an accept into a refusal, or changes the tree.
 * 4. **Two known divergences**, pinned in both directions — see below.
 * 5. **The decimal marker**, which the corpus has no axis for: the same ten
 *    inputs under three locales, whose markers are `.`, U+066B and `,`.
 *
 * These inputs are already preprocessed. `UnicodeMath::Parser#initialize` is a
 * separate slice; every fixture records what the gem's own preprocessing
 * produced, which is why entities appear as `&#x2588;` rather than as the
 * character that was typed.
 */

import { describe, expect, it } from "vitest";
import {
  createUnicodemathGrammar,
  parseUnicodemathPreprocessed,
  unicodemathGrammar,
} from "../../../src/formats/unicodemath/grammar";
import { ParseFailed, type ParseValue, Slice } from "../../../src/pegkit/index";

/**
 * The parse tree with slices flattened to their text, everything else
 * structural — what the Ruby side serialised. Key order is not compared: a
 * deep-equal on plain objects ignores it.
 */
type PlainTree = string | null | PlainTree[] | { [key: string]: PlainTree };

function plain(value: ParseValue): PlainTree {
  if (value === null) return null;
  if (typeof value === "string") return value;
  if (value instanceof Slice) return value.text;
  if (Array.isArray(value)) return value.map(plain);
  const result: Record<string, PlainTree> = {};
  for (const [key, nested] of Object.entries(value)) result[key] = plain(nested);
  return result;
}

const grammar = createUnicodemathGrammar();

function tree(preprocessed: string, which = grammar): PlainTree {
  return plain(which.root.parse(preprocessed));
}

/** True when this grammar refuses the input, as the gem's does. */
function refuses(text: string, which = grammar): boolean {
  try {
    which.root.parse(text);
    return false;
  } catch (error) {
    // Only a typed refusal counts. Anything else is a defect of its own and
    // must reach the runner rather than be reported as "the port refused it".
    if (error instanceof ParseFailed) return true;
    throw error;
  }
}

/** The preprocessed input, and the tree the gem produced for it, verbatim. */
type Fixture = readonly [preprocessed: string, gemTree: string];

