/**
 * Splits a bulk check into several tests.
 *
 * Not cosmetic: one test that parses all 672 upstream expressions runs for ~50
 * seconds without returning to the event loop, and vitest's worker then fails
 * the whole file with `Timeout calling "onTaskUpdate"` — every assertion
 * passing and the run still red. Chunking keeps each test a few seconds long,
 * which is what the reporter needs to stay alive.
 */
function chunks<T>(
  items: readonly T[],
  size: number,
): ReadonlyArray<readonly [number, readonly T[]]> {
  const out: Array<readonly [number, readonly T[]]> = [];
  for (let i = 0; i < items.length; i += size) out.push([i / size + 1, items.slice(i, i + size)]);
  return out;
}

// --- the suites ------------------------------------------------------------

describe("the gem's own UnicodeMath, round-tripped through the grammar", () => {
  it("has the cases it checks against", () => {
    // A reader that silently returned nothing would make every case below
    // vacuous while the suite stayed green.
    expect(CORPUS_FIXTURES.length + CORPUS_REFUSED.length).toBe(88);
    expect(CORPUS_REFUSED.length).toBe(5);
  });

  it.each(CORPUS_FIXTURES)("%s", (preprocessed, gemTree) => {
    expect(tree(preprocessed)).toStrictEqual(JSON.parse(gemTree));
  });

  it.each(CORPUS_REFUSED.map((text) => [text] as const))("refuses %s, as the gem does", (text) => {
    expect(refuses(text)).toBe(true);
  });
});

describe("the upstream unicodemath-tests corpus", () => {
  it("has the cases it checks against", () => {
    expect(UPSTREAM_VERDICTS.length).toBe(670);
    expect(UPSTREAM_FIXTURES.length).toBe(98);
    expect(KNOWN_PEGKIT_CACHE_DIVERGENCES.length).toBe(2);
  });

  it.each(UPSTREAM_FIXTURES)("%s", (preprocessed, gemTree) => {
    expect(tree(preprocessed)).toStrictEqual(JSON.parse(gemTree));
  });

  it.each(chunks(UPSTREAM_VERDICTS, 48))(
    "agrees with the gem on every accept and refusal (chunk %i)",
    (_n, batch) => {
      const wrong = batch.filter(([text, parsed]) => refuses(text) === parsed);
      expect(wrong.map(([text]) => text)).toStrictEqual([]);
    },
  );
});

describe("a sweep over the operators this grammar branches on", () => {
  it("has the cases it checks against", () => {
    expect(SWEEP_FIXTURES.length + SWEEP_REFUSED.length).toBe(4367);
    expect(SWEEP_REFUSED.length).toBe(3444);
  });

  it.each(chunks(SWEEP_FIXTURES, 200))("matches the gem's tree (chunk %i)", (_n, batch) => {
    const wrong: string[] = [];
    for (const [preprocessed, gemTree] of batch) {
      let got: PlainTree;
      try {
        got = tree(preprocessed);
      } catch {
        wrong.push(preprocessed);
        continue;
      }
      if (JSON.stringify(got) !== JSON.stringify(JSON.parse(gemTree))) wrong.push(preprocessed);
    }
    expect(wrong).toStrictEqual([]);
  });

  it.each(chunks(SWEEP_REFUSED, 500))(
    "refuses everything the gem refuses (chunk %i)",
    (_n, batch) => {
      expect(batch.filter((text) => !refuses(text))).toStrictEqual([]);
    },
  );
});

describe("the two divergences pegkit's cache causes", () => {
  it("still produces the gem's tree for neither, and its own for both", () => {
    for (const [preprocessed, gemTree, portTree] of KNOWN_PEGKIT_CACHE_DIVERGENCES) {
      const got = JSON.stringify(tree(preprocessed));
      expect(got).not.toBe(JSON.stringify(JSON.parse(gemTree)));
      expect(got).toBe(JSON.stringify(JSON.parse(portTree)));
    }
  });

  it("reproduces the underlying cache loss on a three-atom grammar", () => {
    // `|x|=b` is the smallest UnicodeMath input that shows it; this is the
    // smallest grammar that shows it at all, so the cause stays legible if the
    // UnicodeMath fixtures ever change.
    expect(tree("|x|=b")).toStrictEqual(
      JSON.parse(
        '{"factor":{"intermediate_exp":{"open_paren":"|","factor":{"atom":{"alphanumeric":"x"}},"close_paren":"|"}},"expr":{"operator":"=","expr":{"factor":{"atom":{"alphanumeric":"b"}}}}}',
      ),
    );
  });
});

describe("the decimal marker", () => {
  const Cases: ReadonlyArray<
    readonly [name: string, marker: string, fixtures: readonly Fixture[]]
  > = [
    ["default", ".", DEFAULT_MARKER_FIXTURES],
    ["ar", "\u066b", ARABIC_MARKER_FIXTURES],
    ["fr", ",", FRENCH_MARKER_FIXTURES],
  ];

  it.each(Cases)("matches the gem under %s", (_name, marker, fixtures) => {
    const localeGrammar = createUnicodemathGrammar(marker);
    for (const [preprocessed, gemTree] of fixtures) {
      expect(tree(preprocessed, localeGrammar)).toStrictEqual(JSON.parse(gemTree));
    }
  });

  /**
   * The axis the corpus cannot reach: U+066B is a decimal marker only under a
   * locale that configures it, and `UnicodeMath::Parser` has already encoded
   * it to `&#x66b;` by the time the grammar sees it.
   */
  it("reads 1&#x66b;5 as one number only under the locale that configures it", () => {
    const arabic = createUnicodemathGrammar("\u066b");
    expect(tree("1&#x66b;5", arabic)).toStrictEqual(
      JSON.parse(
        '{"factor":{"decimal_number":{"whole":{"number":"1"},"decimal":"&#x66b;","fractional":{"number":"5"}}}}',
      ),
    );
    expect(tree("1&#x66b;5")).not.toStrictEqual(tree("1&#x66b;5", arabic));
  });

  it("routes a caller's locale through formatting", () => {
    expect(unicodemathGrammar({ locale: "ar" }).encodedDecimalMarker).toBe("&#x66b;");
    expect(unicodemathGrammar().encodedDecimalMarker).toBe(".");
    expect(plain(parseUnicodemathPreprocessed("1"))).toStrictEqual(
      JSON.parse('{"factor":{"digit":{"number":"1"}}}'),
    );
  });
});

describe("the prefix pairs in the generated tables", () => {
  it("has the cases it checks against", () => {
    expect(PREFIX_PAIR_FIXTURES.length).toBe(105);
  });

  it("matches the gem on both members of every prefix pair", { timeout: 120_000 }, () => {
    const wrong: string[] = [];
    for (const [preprocessed, gemTree] of PREFIX_PAIR_FIXTURES) {
      if (JSON.stringify(tree(preprocessed)) !== JSON.stringify(JSON.parse(gemTree)))
        wrong.push(preprocessed);
    }
    expect(wrong).toStrictEqual([]);
  });
});
